-- 0043_seed_resolution_templates.sql — GÉNÉRÉ par seed.ts (ne pas éditer à la main).
insert into public.resolution_templates
  (code, titre, categorie, texte, majorite, is_information, applicable_ag, obligatoire_pour,
   ordre_suggere, tags, variables, variables_typees, legal_ref, action_type)
values
  ('ag-01', 'Élection du président de séance', 'Assemblée Générale', 'M./Mme {nom_president} est élu(e) président(e) de séance de cette assemblée générale.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], 1, ARRAY['organisation','bureau']::text[], ARRAY['nom_president']::text[], '[{"name":"nom_president","type":"coproprietaire_present","label":"Président de séance","required":true,"filterPresents":true}]'::jsonb, NULL, 'DESIGNATE_BUREAU'),
  ('ag-02', 'Désignation du secrétaire de séance', 'Assemblée Générale', 'M./Mme {nom_secretaire} est désigné(e) comme secrétaire de séance pour la rédaction du procès-verbal.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], 2, ARRAY['organisation','bureau']::text[], ARRAY['nom_secretaire']::text[], '[{"name":"nom_secretaire","type":"coproprietaire_present","label":"Secrétaire de séance","required":true,"filterPresents":true}]'::jsonb, NULL, 'DESIGNATE_BUREAU'),
  ('ag-03', 'Désignation du scrutateur', 'Assemblée Générale', 'M./Mme {nom_scrutateur} est élu(e) scrutateur de cette assemblée générale.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], 3, ARRAY['organisation','bureau']::text[], ARRAY['nom_scrutateur']::text[], '[{"name":"nom_scrutateur","type":"coproprietaire_present","label":"Scrutateur","required":true,"filterPresents":true}]'::jsonb, NULL, 'DESIGNATE_BUREAU'),
  ('ag-04', 'Compte rendu d''activité du conseil syndical', 'Assemblée Générale', 'L''assemblée générale prend connaissance du compte rendu d''activité du conseil syndical pour l''exercice écoulé. Le compte rendu est présenté en séance par le conseil syndical.', 'INFORMATION', true, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], 4, ARRAY['conseil syndical','rapport']::text[], ARRAY[]::text[], '[]'::jsonb, NULL, NULL),
  ('ag-05', 'Quitus au syndic', 'Assemblée Générale', 'L''assemblée générale donne quitus au syndic pour sa gestion au cours de l''exercice du {date_debut} au {date_fin}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 6, ARRAY['syndic','quitus','gestion']::text[], ARRAY['date_debut','date_fin']::text[], '[{"name":"date_debut","type":"date","label":"Date de début d''exercice","required":true},{"name":"date_fin","type":"date","label":"Date de fin d''exercice","required":true}]'::jsonb, NULL, 'GRANT_QUITUS'),
  ('ag-06', 'Approvisionnement du fonds de travaux (loi ALUR)', 'Assemblée Générale', 'Conformément à l''article 14-2 de la loi du 10 juillet 1965, l''assemblée générale décide de provisionner le fonds de travaux à hauteur de {pourcentage}% du budget prévisionnel de l''exercice, soit {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 10, ARRAY['fonds travaux','ALUR','budget']::text[], ARRAY['pourcentage','montant']::text[], '[{"name":"pourcentage","type":"pourcentage","label":"Pourcentage du budget","required":true},{"name":"montant","type":"montant","label":"Montant du fonds (calculé)","required":true}]'::jsonb, NULL, 'CREATE_ALUR_FUND'),
  ('ag-07', 'Calendrier de financement du budget prévisionnel', 'Assemblée Générale', 'L''assemblée générale approuve le calendrier de financement du budget prévisionnel selon les modalités suivantes : {modalites_paiement_budget}. Les appels de fonds seront exigibles aux dates suivantes : {dates_echeances_budget}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 9, ARRAY['budget','appels de fonds','échéancier']::text[], ARRAY['modalites_paiement_budget','dates_echeances_budget']::text[], '[{"name":"modalites_paiement_budget","type":"modalites_paiement_budget","label":"Modalités de paiement","required":true},{"name":"dates_echeances_budget","type":"text","label":"Dates d''échéances","placeholder":"Générées automatiquement selon la modalité choisie","required":true}]'::jsonb, NULL, 'SCHEDULE_BUDGET_PAYMENTS'),
  ('ag-08', 'Seuil de consultation du conseil syndical', 'Assemblée Générale', 'L''assemblée générale fixe à {montant} euros le seuil au-delà duquel le syndic devra consulter le conseil syndical avant d''engager toute dépense non prévue au budget.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 13, ARRAY['conseil syndical','seuil','dépenses']::text[], ARRAY['montant']::text[], '[]'::jsonb, NULL, NULL),
  ('ag-09', 'Seuil de mise en concurrence', 'Assemblée Générale', 'L''assemblée générale fixe à {montant} euros le seuil au-delà duquel le syndic devra obligatoirement mettre en concurrence au moins trois entreprises avant de passer une commande.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 14, ARRAY['mise en concurrence','seuil','marchés']::text[], ARRAY['montant']::text[], '[]'::jsonb, NULL, NULL),
  ('ag-10', 'Calendrier de financement du fonds de travaux', 'Assemblée Générale', 'L''assemblée générale approuve le calendrier de financement du fonds de travaux selon les modalités suivantes : {modalites_paiement_fonds}. Les versements au fonds de travaux seront exigibles aux dates suivantes : {dates_echeances_fonds}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 11, ARRAY['fonds travaux','appels de fonds','échéancier']::text[], ARRAY['modalites_paiement_fonds','dates_echeances_fonds']::text[], '[{"name":"modalites_paiement_fonds","type":"modalites_paiement_budget","label":"Modalités de paiement","required":true},{"name":"dates_echeances_fonds","type":"text","label":"Dates d''échéances","placeholder":"Générées automatiquement selon la modalité choisie","required":true}]'::jsonb, NULL, 'SCHEDULE_ALUR_PAYMENTS'),
  ('travaux-01', 'Vote de travaux', 'Travaux', 'L''assemblée générale décide de réaliser les travaux suivants : {description}. Le montant des travaux est estimé à {montant} euros. Le syndic est autorisé à lancer une consultation auprès d''au moins trois entreprises.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['travaux','devis','consultation']::text[], ARRAY['description','montant']::text[], '[]'::jsonb, NULL, 'CREATE_WORK_BUDGET'),
  ('travaux-02', 'Vote de travaux et honoraires', 'Travaux', 'L''assemblée générale décide de réaliser les travaux suivants : {description} pour un montant estimé à {montant} euros, et d''engager des honoraires de maîtrise d''œuvre pour un montant de {montant_honoraires} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['travaux','maîtrise d''œuvre','honoraires']::text[], ARRAY['description','montant','montant_honoraires']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-03', 'Études et diagnostic', 'Travaux', 'L''assemblée générale autorise le syndic à faire réaliser une étude/diagnostic concernant {objet} pour un montant maximum de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['études','diagnostic','audit']::text[], ARRAY['objet','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-04', 'Réalisation d''une étude de faisabilité pour l''installation de bornes de recharge pour véhicules électriques', 'Travaux', 'L''assemblée générale autorise le syndic à faire réaliser une étude de faisabilité technique et financière pour l''installation de bornes de recharge pour véhicules électriques dans la copropriété, pour un montant maximum de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['IRVE','borne de recharge','véhicule électrique','étude']::text[], ARRAY['montant']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-05', 'Travaux d''urgence', 'Travaux', 'L''assemblée générale autorise le syndic à réaliser en urgence les travaux suivants : {description}, sans limitation de montant si la sécurité l''exige.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['urgence','sécurité','sinistre']::text[], ARRAY['description']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-06', 'Travaux d''amélioration énergétique', 'Travaux', 'L''assemblée générale décide de réaliser des travaux d''amélioration énergétique : {description}, pour un montant de {montant} euros, permettant une économie d''énergie estimée à {pourcentage}%.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['rénovation énergétique','isolation','DPE','économie d''énergie']::text[], ARRAY['description','montant','pourcentage']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-07', 'Travaux de mise en conformité', 'Travaux', 'L''assemblée générale décide de réaliser les travaux de mise en conformité suivants : {description}, imposés par {autorite}, pour un montant de {montant} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['mise en conformité','réglementation','normes']::text[], ARRAY['description','autorite','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-08', 'Ravalement de façades', 'Travaux', 'L''assemblée générale décide de réaliser le ravalement des façades de l''immeuble selon le devis de l''entreprise {entreprise} d''un montant de {montant} euros TTC. Les travaux débuteront le {date_debut} pour une durée prévisionnelle de {duree} mois.', 'ART_25', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['ravalement','façade','gros travaux']::text[], ARRAY['entreprise','montant','date_debut','duree']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-09', 'Réfection de la toiture', 'Travaux', 'L''assemblée générale décide de réaliser la réfection de la toiture selon le devis de l''entreprise {entreprise} d''un montant de {montant} euros TTC. Nature des travaux : {description}.', 'ART_25', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['toiture','couverture','gros travaux','étanchéité']::text[], ARRAY['entreprise','montant','description']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-10', 'Modernisation ou remplacement de l''ascenseur', 'Travaux', 'L''assemblée générale décide de procéder à {type_travaux} de l''ascenseur selon le devis de l''entreprise {entreprise} d''un montant de {montant} euros TTC. Cette décision fait suite au rapport de contrôle technique.', 'ART_25', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['ascenseur','mise aux normes','gros travaux']::text[], ARRAY['type_travaux','entreprise','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('travaux-11', 'Plan pluriannuel de travaux (PPT)', 'Travaux', 'L''assemblée générale adopte le plan pluriannuel de travaux présenté par {auteur} pour la période {periode}. Ce plan prévoit un montant total de travaux de {montant_total} euros, avec une provision annuelle de {provision_annuelle} euros.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['PPT','planification','entretien','loi Climat']::text[], ARRAY['auteur','periode','montant_total','provision_annuelle']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-01', 'Appel de fonds exceptionnel', 'Finances', 'L''assemblée générale décide de lancer un appel de fonds exceptionnel d''un montant de {montant} euros pour financer {objet}. Cet appel sera réparti selon les tantièmes et exigible le {date}.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['appel de fonds','financement','travaux']::text[], ARRAY['montant','objet','date']::text[], '[{"name":"montant","type":"montant","label":"Montant de l''appel","required":true},{"name":"objet","type":"text","label":"Objet de l''appel","required":true},{"name":"date","type":"date","label":"Date d''exigibilité","required":true}]'::jsonb, NULL, 'CREATE_EXCEPTIONAL_CALL'),
  ('fin-02', 'Instauration d''une avance de trésorerie prévue par le règlement de copropriété', 'Finances', 'L''assemblée générale décide d''instaurer une avance de trésorerie, conformément à l''article {article} du règlement de copropriété, d''un montant de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['trésorerie','avance','règlement']::text[], ARRAY['article','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-03', 'Instauration d''une avance de trésorerie non prévue par le règlement de copropriété', 'Finances', 'L''assemblée générale décide d''instaurer une avance de trésorerie, bien que non prévue par le règlement de copropriété, d''un montant de {montant} euros pour {objet}.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['trésorerie','avance']::text[], ARRAY['montant','objet']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-04', 'Ajustement de l''avance de trésorerie', 'Finances', 'L''assemblée générale décide d''ajuster le montant de l''avance de trésorerie, qui passe de {montant_ancien} euros à {montant_nouveau} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['trésorerie','avance','ajustement']::text[], ARRAY['montant_ancien','montant_nouveau']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-05', 'Approbation des comptes', 'Finances', 'L''assemblée générale approuve les comptes de l''exercice du {date_debut} au {date_fin}, faisant apparaître un résultat de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 5, ARRAY['comptes','approbation','exercice']::text[], ARRAY['date_debut','date_fin','montant']::text[], '[{"name":"date_debut","type":"date","label":"Date de début d''exercice","required":true},{"name":"date_fin","type":"date","label":"Date de fin d''exercice","required":true},{"name":"montant","type":"montant","label":"Résultat de l''exercice","required":true}]'::jsonb, NULL, 'APPROVE_ACCOUNTS'),
  ('fin-06', 'Approbation du budget prévisionnel', 'Finances', 'L''assemblée générale approuve le budget prévisionnel pour l''exercice du {date_debut} au {date_fin}, arrêté à la somme de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 8, ARRAY['budget','prévisionnel','exercice']::text[], ARRAY['date_debut','date_fin','montant']::text[], '[{"name":"date_debut","type":"date","label":"Date de début d''exercice","required":true},{"name":"date_fin","type":"date","label":"Date de fin d''exercice","required":true},{"name":"montant","type":"montant","label":"Montant total du budget","required":true}]'::jsonb, NULL, 'CREATE_BUDGET'),
  ('fin-07', 'Autorisation d''ouvrir un compte bancaire séparé (syndic non professionnel)', 'Finances', 'L''assemblée générale autorise le syndic non professionnel à ouvrir un compte bancaire séparé au nom du syndicat des copropriétaires auprès de {banque}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compte bancaire','syndic bénévole']::text[], ARRAY['banque']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-08', 'Changement du représentant légal auprès des services bancaires', 'Finances', 'L''assemblée générale décide de modifier le représentant légal du syndicat des copropriétaires auprès des services bancaires. M./Mme {nom} est désigné(e) en remplacement de M./Mme {nom_ancien}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['banque','représentant légal']::text[], ARRAY['nom','nom_ancien']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-09', 'Souscription d''un emprunt collectif', 'Finances', 'L''assemblée générale autorise la souscription d''un emprunt collectif d''un montant de {montant} euros sur une durée de {duree} ans, au taux maximal de {taux}%, destiné au financement de {objet}.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['emprunt','financement','prêt collectif']::text[], ARRAY['montant','duree','taux','objet']::text[], '[]'::jsonb, NULL, NULL),
  ('fin-10', 'Prise d''acte de la situation de trésorerie', 'Finances', 'L''assemblée générale prend acte de la situation de trésorerie au {date}, présentant un solde de {solde} euros.', 'INFORMATION', true, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['trésorerie','situation financière']::text[], ARRAY['date','solde']::text[], '[{"name":"date","type":"date","label":"Date de la situation","required":true},{"name":"solde","type":"montant","label":"Solde de trésorerie","required":true}]'::jsonb, NULL, NULL),
  ('cs-01', 'Désignation des membres suppléants du conseil syndical', 'Conseil syndical et syndic', 'L''assemblée générale élit les copropriétaires suivants en qualité de membres suppléants du conseil syndical : {noms}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['conseil syndical','élection','suppléants']::text[], ARRAY['noms']::text[], '[]'::jsonb, NULL, NULL),
  ('cs-02', 'Élection des membres titulaires du conseil syndical', 'Conseil syndical et syndic', 'L''assemblée générale élit les copropriétaires suivants en qualité de membres titulaires du conseil syndical : {noms}. Leurs mandats prendront effet à compter de la clôture de la présente assemblée.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 12, ARRAY['conseil syndical','élection','titulaires']::text[], ARRAY['noms']::text[], '[]'::jsonb, 'Loi du 10 juillet 1965, art. 25 (passerelle 25-1)', 'ELECT_COUNCIL'),
  ('cs-03', 'Révocation d''un membre du conseil syndical', 'Conseil syndical et syndic', 'L''assemblée générale décide de révoquer M./Mme {nom} de ses fonctions de membre du conseil syndical pour le motif suivant : {motif}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['conseil syndical','révocation']::text[], ARRAY['nom','motif']::text[], '[]'::jsonb, NULL, NULL),
  ('cs-04', 'Nomination du syndic', 'Conseil syndical et syndic', 'L''assemblée générale nomme {nom_syndic} en qualité de syndic de la copropriété pour une durée de {duree_mandat_mois}, à compter du {date_debut}. Les honoraires sont fixés à {honoraires_annuels_ttc} TTC par an.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['syndic','nomination','contrat']::text[], ARRAY['nom_syndic','duree_mandat_mois','date_debut','honoraires_annuels_ttc']::text[], '[{"name":"nom_syndic","type":"gestionnaire","label":"Nom du syndic","required":true},{"name":"duree_mandat_mois","type":"duree_mois","label":"Durée du mandat (3 à 36 mois)","placeholder":"Ex: 12","required":true},{"name":"date_debut","type":"date","label":"Date de début du mandat","required":true},{"name":"honoraires_annuels_ttc","type":"montant","label":"Honoraires annuels TTC","required":true}]'::jsonb, 'Loi du 10 juillet 1965, art. 25 (passerelle 25-1)', 'APPOINT_SYNDIC'),
  ('cs-05', 'Renouvellement du mandat du syndic', 'Conseil syndical et syndic', 'L''assemblée générale renouvelle le mandat du syndic {nom_syndic} pour une durée de {duree_mandat_mois}. Les honoraires sont fixés à {honoraires_annuels_ttc} TTC par an.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY['ORDINAIRE']::text[], 7, ARRAY['syndic','renouvellement','contrat']::text[], ARRAY['nom_syndic','duree_mandat_mois','honoraires_annuels_ttc']::text[], '[{"name":"nom_syndic","type":"gestionnaire","label":"Nom du syndic","required":true},{"name":"duree_mandat_mois","type":"duree_mois","label":"Durée du mandat (3 à 36 mois)","placeholder":"Ex: 12","required":true},{"name":"honoraires_annuels_ttc","type":"montant","label":"Honoraires annuels TTC","required":true}]'::jsonb, 'Loi du 10 juillet 1965, art. 25 (passerelle 25-1)', 'APPOINT_SYNDIC'),
  ('cs-06', 'Révocation du syndic', 'Conseil syndical et syndic', 'L''assemblée générale décide de révoquer {nom_syndic} de ses fonctions de syndic pour le motif suivant : {motif}. La révocation prendra effet le {date}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['syndic','révocation']::text[], ARRAY['nom_syndic','motif','date']::text[], '[]'::jsonb, NULL, NULL),
  ('cs-07', 'Augmentation des honoraires du syndic', 'Conseil syndical et syndic', 'L''assemblée générale accepte l''augmentation des honoraires du syndic, qui passent de {montant_ancien_ttc} TTC à {montant_nouveau_ttc} TTC par an.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['syndic','honoraires','augmentation']::text[], ARRAY['montant_ancien_ttc','montant_nouveau_ttc']::text[], '[{"name":"montant_ancien_ttc","type":"montant","label":"Ancien montant TTC","required":true},{"name":"montant_nouveau_ttc","type":"montant","label":"Nouveau montant TTC","required":true}]'::jsonb, NULL, NULL),
  ('cs-08', 'Mandat au conseil syndical', 'Conseil syndical et syndic', 'L''assemblée générale donne mandat au conseil syndical pour {objet}, dans la limite d''un montant de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['conseil syndical','mandat','délégation']::text[], ARRAY['objet','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('cs-09', 'Rémunération exceptionnelle du conseil syndical', 'Conseil syndical et syndic', 'L''assemblée générale décide d''allouer une rémunération exceptionnelle de {montant} euros au conseil syndical pour {motif}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['conseil syndical','rémunération']::text[], ARRAY['montant','motif']::text[], '[]'::jsonb, NULL, NULL),
  ('cs-10', 'Honoraires forfaitaires du syndic', 'Conseil syndical et syndic', 'L''assemblée générale fixe les honoraires forfaitaires du syndic pour l''année {annee} à {montant_ttc} TTC, répartis selon les tantièmes.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['syndic','honoraires']::text[], ARRAY['annee','montant_ttc']::text[], '[{"name":"annee","type":"text","label":"Année","placeholder":"Ex: 2026","required":true},{"name":"montant_ttc","type":"montant","label":"Montant TTC","required":true}]'::jsonb, NULL, NULL),
  ('cs-11', 'Honoraires complémentaires du syndic', 'Conseil syndical et syndic', 'L''assemblée générale accepte de verser au syndic des honoraires complémentaires d''un montant de {montant_ttc} TTC pour {prestation}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['syndic','honoraires','complémentaires']::text[], ARRAY['montant_ttc','prestation']::text[], '[{"name":"montant_ttc","type":"montant","label":"Montant TTC","required":true},{"name":"prestation","type":"text","label":"Prestation concernée","placeholder":"Ex: suivi des travaux de ravalement","required":true}]'::jsonb, NULL, NULL),
  ('contrat-01', 'Souscription d''un contrat', 'Contrats', 'L''assemblée générale autorise le syndic à souscrire un contrat de {type} auprès de {prestataire} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['contrat','souscription','prestataire']::text[], ARRAY['type','prestataire','montant']::text[], '[]'::jsonb, NULL, 'MANAGE_CONTRACT'),
  ('contrat-02', 'Renouvellement d''un contrat', 'Contrats', 'L''assemblée générale approuve le renouvellement du contrat de {type} avec {prestataire} pour une durée de {duree} an(s), au tarif de {montant} euros par an.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['contrat','renouvellement','prestataire']::text[], ARRAY['type','prestataire','duree','montant']::text[], '[]'::jsonb, NULL, 'MANAGE_CONTRACT'),
  ('contrat-03', 'Résiliation d''un contrat', 'Contrats', 'L''assemblée générale décide de résilier le contrat de {type} avec {prestataire}, avec effet au {date}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['contrat','résiliation','prestataire']::text[], ARRAY['type','prestataire','date']::text[], '[]'::jsonb, NULL, 'MANAGE_CONTRACT'),
  ('contrat-04', 'Contrat d''assurance multirisque', 'Contrats', 'L''assemblée générale approuve la souscription/le renouvellement du contrat d''assurance multirisque de l''immeuble auprès de {compagnie} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['assurance','multirisque','contrat']::text[], ARRAY['compagnie','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('contrat-05', 'Contrat d''entretien ascenseur', 'Contrats', 'L''assemblée générale autorise le syndic à signer un contrat d''entretien des ascenseurs avec {prestataire} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['ascenseur','entretien','contrat']::text[], ARRAY['prestataire','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('contrat-06', 'Contrat d''entretien chaudière', 'Contrats', 'L''assemblée générale approuve le contrat d''entretien de la chaudière avec {prestataire} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['chaudière','chauffage','entretien','contrat']::text[], ARRAY['prestataire','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('contrat-07', 'Contrat de nettoyage', 'Contrats', 'L''assemblée générale autorise le syndic à signer un contrat de nettoyage des parties communes avec {prestataire} pour un montant de {montant} euros par {periodicite}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['nettoyage','entretien','contrat']::text[], ARRAY['prestataire','montant','periodicite']::text[], '[]'::jsonb, NULL, NULL),
  ('contrat-08', 'Contrat d''espaces verts', 'Contrats', 'L''assemblée générale approuve le contrat d''entretien des espaces verts avec {prestataire} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['espaces verts','jardinage','entretien','contrat']::text[], ARRAY['prestataire','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('contrat-09', 'Contrat de télésurveillance', 'Contrats', 'L''assemblée générale autorise la souscription d''un contrat de télésurveillance auprès de {prestataire} pour un montant mensuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['sécurité','télésurveillance','contrat']::text[], ARRAY['prestataire','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('justice-01', 'Engagement d''une action en justice', 'Action en justice', 'L''assemblée générale autorise le syndic à engager une action en justice contre {partie} concernant {objet}, et à mandater Maître {avocat} pour défendre les intérêts du syndicat.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['justice','contentieux','avocat','procédure']::text[], ARRAY['partie','objet','avocat']::text[], '[]'::jsonb, NULL, NULL),
  ('justice-02', 'Désistement d''une action en justice', 'Action en justice', 'L''assemblée générale autorise le syndic à se désister de l''action en justice engagée contre {partie} concernant {objet}.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['justice','désistement','contentieux']::text[], ARRAY['partie','objet']::text[], '[]'::jsonb, NULL, NULL),
  ('imp-01', 'Mise en demeure pour impayés', 'Impayés', 'L''assemblée générale autorise le syndic à adresser une mise en demeure à M./Mme {nom} concernant des impayés d''un montant de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['impayés','mise en demeure','recouvrement']::text[], ARRAY['nom','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('imp-02', 'Engagement d''une procédure contentieuse pour impayés', 'Impayés', 'L''assemblée générale autorise le syndic à engager une procédure contentieuse contre M./Mme {nom} pour des impayés d''un montant de {montant} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['impayés','contentieux','recouvrement','procédure']::text[], ARRAY['nom','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('imp-03', 'Remise gracieuse de pénalités de retard', 'Impayés', 'L''assemblée générale décide d''accorder une remise gracieuse des pénalités de retard à M./Mme {nom} pour un montant de {montant} euros, suite à {motif}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['impayés','remise','pénalités']::text[], ARRAY['nom','montant','motif']::text[], '[]'::jsonb, NULL, NULL),
  ('reglement-01', 'Modification du règlement de copropriété', 'Modification du règlement', 'L''assemblée générale décide de modifier le règlement de copropriété comme suit : {description}.', 'ART_26', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['règlement','modification','copropriété']::text[], ARRAY['description']::text[], '[]'::jsonb, NULL, NULL),
  ('reglement-02', 'Modification de la destination de l''immeuble', 'Modification du règlement', 'L''assemblée générale décide de modifier la destination de l''immeuble pour permettre {description}.', 'UNANIMITE', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['règlement','destination','unanimité']::text[], ARRAY['description']::text[], '[]'::jsonb, NULL, NULL),
  ('reglement-03', 'Changement d''affectation d''un lot', 'Modification du règlement', 'L''assemblée générale autorise M./Mme {nom} à changer l''affectation du lot n°{numero} de {affectation_ancienne} à {affectation_nouvelle}.', 'ART_26', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['lot','affectation','changement']::text[], ARRAY['nom','numero','affectation_ancienne','affectation_nouvelle']::text[], '[]'::jsonb, NULL, NULL),
  ('reglement-04', 'Répartition des charges', 'Modification du règlement', 'L''assemblée générale décide de modifier la répartition des charges comme suit : {description}.', 'UNANIMITE', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['charges','répartition','unanimité']::text[], ARRAY['description']::text[], '[]'::jsonb, NULL, NULL),
  ('reglement-05', 'Modification de la répartition des tantièmes', 'Modification du règlement', 'L''assemblée générale décide de modifier la répartition des tantièmes suite à {motif}. Nouvelle répartition : {repartition}.', 'UNANIMITE', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['tantièmes','répartition','unanimité']::text[], ARRAY['motif','repartition']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-01', 'Achat de compteurs divisionnaires (eau froide et/ou eau chaude)', 'Compteurs', 'L''assemblée générale décide d''installer des compteurs divisionnaires {type} dans la copropriété. Le montant des travaux est estimé à {montant} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compteurs','eau','installation']::text[], ARRAY['type','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-02', 'Signature d''un contrat de location-entretien-relève des compteurs divisionnaires', 'Compteurs', 'L''assemblée générale autorise le syndic à signer un contrat de location-entretien-relève des compteurs divisionnaires avec {prestataire} pour un montant annuel de {montant} euros.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compteurs','contrat','relève']::text[], ARRAY['prestataire','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-03', 'Recours en cas de refus d''installation des compteurs divisionnaires', 'Compteurs', 'L''assemblée générale autorise le syndic à engager un recours contre M./Mme {nom} pour refus d''installation, de maintenance ou de relève des compteurs divisionnaires.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compteurs','recours','refus']::text[], ARRAY['nom']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-04', 'Application d''un forfait de consommation pour compteurs non relevés', 'Compteurs', 'L''assemblée générale décide d''appliquer un forfait de consommation {type} de {montant} euros pour les lots dont les compteurs n''ont pas pu être relevés.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compteurs','forfait','consommation']::text[], ARRAY['type','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-05', 'Remplacement des compteurs divisionnaires', 'Compteurs', 'L''assemblée générale décide de remplacer les compteurs divisionnaires {type} obsolètes pour un montant de {montant} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['compteurs','remplacement']::text[], ARRAY['type','montant']::text[], '[]'::jsonb, NULL, NULL),
  ('compteur-06', 'Individualisation des frais de chauffage', 'Compteurs', 'L''assemblée générale décide de procéder à l''individualisation des frais de chauffage par l''installation de compteurs, pour un montant estimé à {montant} euros.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['chauffage','individualisation','compteurs']::text[], ARRAY['montant']::text[], '[]'::jsonb, NULL, NULL),
  ('conduite-01', 'Adoption d''un règlement intérieur', 'Règles de bonne conduite', 'L''assemblée générale adopte le règlement intérieur de la copropriété tel que présenté, qui précise notamment les règles concernant {points_importants}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['règlement intérieur','règles','vie commune']::text[], ARRAY['points_importants']::text[], '[]'::jsonb, NULL, NULL),
  ('conduite-02', 'Interdiction de certains comportements', 'Règles de bonne conduite', 'L''assemblée générale décide d''interdire formellement {comportement} dans les parties communes de l''immeuble.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['interdiction','comportement','parties communes']::text[], ARRAY['comportement']::text[], '[]'::jsonb, NULL, NULL),
  ('conduite-03', 'Mise en place d''horaires pour travaux', 'Règles de bonne conduite', 'L''assemblée générale décide de fixer les horaires autorisés pour les travaux bruyants : {horaires}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['travaux','horaires','bruit']::text[], ARRAY['horaires']::text[], '[]'::jsonb, NULL, NULL),
  ('securite-01', 'Mise aux normes des installations électriques', 'Sécurité et conformité', 'L''assemblée générale décide de faire réaliser la mise aux normes des installations électriques des parties communes, conformément au diagnostic électrique établi par {nom_diagnostiqueur} le {date_diagnostic}. Le montant des travaux est estimé à {montant_travaux} TTC. Les travaux seront confiés à l''entreprise {nom_entreprise}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['électricité','normes','sécurité','diagnostic']::text[], ARRAY[]::text[], '[{"name":"nom_diagnostiqueur","type":"text","label":"Nom du diagnostiqueur","required":true},{"name":"date_diagnostic","type":"date","label":"Date du diagnostic","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true},{"name":"nom_entreprise","type":"text","label":"Nom de l''entreprise","required":true}]'::jsonb, NULL, NULL),
  ('securite-02', 'Installation d''un système de vidéosurveillance', 'Sécurité et conformité', 'L''assemblée générale décide d''installer un système de vidéosurveillance dans les parties communes de l''immeuble. Le système comprendra {nombre_cameras} caméras placées aux emplacements suivants : {emplacements}. Le coût d''installation est de {montant_installation} TTC et le coût de maintenance annuel de {montant_maintenance} TTC. La déclaration à la CNIL sera effectuée par le syndic.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['vidéosurveillance','sécurité','caméras','CNIL']::text[], ARRAY[]::text[], '[{"name":"nombre_cameras","type":"numero","label":"Nombre de caméras","required":true},{"name":"emplacements","type":"textarea","label":"Emplacements des caméras","required":true},{"name":"montant_installation","type":"montant","label":"Coût d''installation TTC","required":true},{"name":"montant_maintenance","type":"montant","label":"Coût maintenance annuel TTC","required":true}]'::jsonb, NULL, NULL),
  ('securite-03', 'Mise en conformité des garde-corps et balcons', 'Sécurité et conformité', 'L''assemblée générale décide de procéder à la mise en conformité des garde-corps et balcons selon les normes NF P01-012 et NF P01-013. Le montant des travaux est estimé à {montant_travaux} TTC. Les travaux concernent {description_travaux}.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['garde-corps','balcons','normes','sécurité']::text[], ARRAY[]::text[], '[{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true},{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true}]'::jsonb, NULL, NULL),
  ('securite-04', 'Installation de détecteurs de fumée', 'Sécurité et conformité', 'L''assemblée générale décide d''installer des détecteurs avertisseurs autonomes de fumée (DAAF) dans les parties communes de l''immeuble. Le nombre d''équipements est de {nombre_detecteurs}. Le coût total est de {montant_total} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['incendie','détecteurs','fumée','sécurité']::text[], ARRAY[]::text[], '[{"name":"nombre_detecteurs","type":"numero","label":"Nombre de détecteurs","required":true},{"name":"montant_total","type":"montant","label":"Coût total TTC","required":true}]'::jsonb, NULL, NULL),
  ('securite-05', 'Mise aux normes accessibilité PMR', 'Sécurité et conformité', 'L''assemblée générale décide de réaliser des travaux de mise en accessibilité pour les personnes à mobilité réduite (PMR). Les travaux comprennent : {description_travaux}. Le montant total est estimé à {montant_travaux} TTC.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['accessibilité','PMR','handicap','normes']::text[], ARRAY[]::text[], '[{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true}]'::jsonb, NULL, NULL),
  ('securite-06', 'Contrôle et entretien des extincteurs', 'Sécurité et conformité', 'L''assemblée générale approuve le contrat de maintenance des extincteurs avec la société {nom_societe} pour un montant annuel de {montant_annuel} TTC. Le contrat prévoit {nombre_visites} visites de contrôle par an.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['extincteurs','incendie','sécurité','maintenance']::text[], ARRAY[]::text[], '[{"name":"nom_societe","type":"text","label":"Nom de la société","required":true},{"name":"montant_annuel","type":"montant","label":"Montant annuel TTC","required":true},{"name":"nombre_visites","type":"numero","label":"Nombre de visites/an","required":true}]'::jsonb, NULL, NULL),
  ('securite-07', 'Diagnostic amiante des parties communes', 'Sécurité et conformité', 'L''assemblée générale décide de faire réaliser un diagnostic amiante des parties communes par un organisme certifié. Le coût du diagnostic est de {montant_diagnostic} TTC. En cas de présence d''amiante, le syndic convoquera une assemblée générale extraordinaire pour décider des travaux nécessaires.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['amiante','diagnostic','sécurité','santé']::text[], ARRAY[]::text[], '[{"name":"montant_diagnostic","type":"montant","label":"Coût du diagnostic TTC","required":true}]'::jsonb, NULL, NULL),
  ('securite-08', 'Installation d''un système de contrôle d''accès', 'Sécurité et conformité', 'L''assemblée générale décide d''installer un système de contrôle d''accès par {type_systeme} pour les entrées de l''immeuble. Chaque copropriétaire recevra {nombre_badges} badge(s)/clé(s). Le coût d''installation est de {montant_installation} TTC et les badges/clés supplémentaires seront facturés {prix_badge} TTC l''unité.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['contrôle d''accès','badge','digicode','sécurité']::text[], ARRAY[]::text[], '[{"name":"type_systeme","type":"text","label":"Type de système (badge, digicode, etc.)","required":true},{"name":"nombre_badges","type":"numero","label":"Nombre de badges par lot","required":true},{"name":"montant_installation","type":"montant","label":"Coût d''installation TTC","required":true},{"name":"prix_badge","type":"montant","label":"Prix badge supplémentaire TTC","required":true}]'::jsonb, NULL, NULL),
  ('energie-01', 'Réalisation d''un audit énergétique', 'Énergie et environnement', 'L''assemblée générale décide de faire réaliser un audit énergétique de l''immeuble par {nom_bureau_etudes}. Le coût de l''audit est de {montant_audit} TTC. Les résultats seront présentés lors d''une prochaine assemblée générale avec les préconisations de travaux.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['audit énergétique','DPE','énergie','environnement']::text[], ARRAY[]::text[], '[{"name":"nom_bureau_etudes","type":"text","label":"Bureau d''études","required":true},{"name":"montant_audit","type":"montant","label":"Coût de l''audit TTC","required":true}]'::jsonb, NULL, NULL),
  ('energie-02', 'Installation de panneaux solaires', 'Énergie et environnement', 'L''assemblée générale décide d''installer des panneaux solaires photovoltaïques sur la toiture de l''immeuble. La puissance installée sera de {puissance_kwc} kWc. Le montant des travaux est de {montant_travaux} TTC. La production sera {utilisation} (autoconsommation collective / revente EDF). Les économies annuelles estimées sont de {economies_annuelles}.', 'ART_26', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['solaire','photovoltaïque','énergie renouvelable','environnement']::text[], ARRAY[]::text[], '[{"name":"puissance_kwc","type":"numero","label":"Puissance en kWc","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true},{"name":"utilisation","type":"text","label":"Mode d''utilisation","required":true},{"name":"economies_annuelles","type":"montant","label":"Économies annuelles estimées","required":true}]'::jsonb, NULL, NULL),
  ('energie-03', 'Remplacement de la chaudière collective', 'Énergie et environnement', 'L''assemblée générale décide de remplacer la chaudière collective par une chaudière {type_chaudiere} de marque {marque_modele}. Le montant des travaux est de {montant_travaux} TTC. Les économies d''énergie attendues sont de {pourcentage_economie}% par an.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['chaudière','chauffage','énergie','économies']::text[], ARRAY[]::text[], '[{"name":"type_chaudiere","type":"text","label":"Type de chaudière","required":true},{"name":"marque_modele","type":"text","label":"Marque et modèle","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true},{"name":"pourcentage_economie","type":"pourcentage","label":"Économies attendues (%)","required":true}]'::jsonb, NULL, NULL),
  ('energie-04', 'Isolation thermique par l''extérieur (ITE)', 'Énergie et environnement', 'L''assemblée générale décide de réaliser l''isolation thermique par l''extérieur (ITE) des façades de l''immeuble. Les travaux comprennent : {description_travaux}. Le montant total est de {montant_travaux} TTC. Les aides disponibles (MaPrimeRénov'', CEE) sont estimées à {montant_aides}.', 'ART_25', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['isolation','ITE','façade','énergie','rénovation']::text[], ARRAY[]::text[], '[{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true},{"name":"montant_travaux","type":"montant","label":"Montant total TTC","required":true},{"name":"montant_aides","type":"montant","label":"Montant des aides estimées","required":false}]'::jsonb, NULL, NULL),
  ('energie-05', 'Remplacement des fenêtres des parties communes', 'Énergie et environnement', 'L''assemblée générale décide de remplacer les fenêtres des parties communes par des fenêtres {type_vitrage}. Le nombre de fenêtres concernées est de {nombre_fenetres}. Le montant total est de {montant_travaux} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['fenêtres','vitrage','isolation','énergie']::text[], ARRAY[]::text[], '[{"name":"type_vitrage","type":"text","label":"Type de vitrage (double, triple)","required":true},{"name":"nombre_fenetres","type":"numero","label":"Nombre de fenêtres","required":true},{"name":"montant_travaux","type":"montant","label":"Montant total TTC","required":true}]'::jsonb, NULL, NULL),
  ('energie-06', 'Installation de bornes de recharge véhicules électriques', 'Énergie et environnement', 'L''assemblée générale décide d''installer {nombre_bornes} borne(s) de recharge pour véhicules électriques dans le parking de la copropriété. Le montant des travaux d''infrastructure est de {montant_infrastructure} TTC. Le coût par borne individuelle à la charge de chaque copropriétaire demandeur sera de {cout_borne} TTC.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['véhicule électrique','borne','recharge','parking','environnement']::text[], ARRAY[]::text[], '[{"name":"nombre_bornes","type":"numero","label":"Nombre de bornes","required":true},{"name":"montant_infrastructure","type":"montant","label":"Coût infrastructure TTC","required":true},{"name":"cout_borne","type":"montant","label":"Coût par borne TTC","required":true}]'::jsonb, NULL, NULL),
  ('energie-07', 'Mise en place du tri sélectif', 'Énergie et environnement', 'L''assemblée générale décide de mettre en place le tri sélectif dans la copropriété. L''aménagement comprend : {description_amenagement}. Le coût des équipements est de {montant_equipement} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['tri sélectif','déchets','environnement','poubelles']::text[], ARRAY[]::text[], '[{"name":"description_amenagement","type":"textarea","label":"Description de l''aménagement","required":true},{"name":"montant_equipement","type":"montant","label":"Coût des équipements TTC","required":true}]'::jsonb, NULL, NULL),
  ('energie-08', 'Installation de robinets thermostatiques', 'Énergie et environnement', 'L''assemblée générale décide d''installer des robinets thermostatiques sur tous les radiateurs des parties communes et des logements. Le nombre de robinets à installer est de {nombre_robinets}. Le coût total est de {montant_total} TTC, soit {cout_unitaire} par robinet.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['robinets','thermostatique','chauffage','énergie']::text[], ARRAY[]::text[], '[{"name":"nombre_robinets","type":"numero","label":"Nombre de robinets","required":true},{"name":"montant_total","type":"montant","label":"Coût total TTC","required":true},{"name":"cout_unitaire","type":"montant","label":"Coût unitaire TTC","required":true}]'::jsonb, NULL, NULL),
  ('parking-01', 'Réfection du revêtement du parking', 'Parking et espaces communs', 'L''assemblée générale décide de procéder à la réfection du revêtement du parking souterrain. Les travaux comprennent : {description_travaux}. Le montant total est de {montant_travaux} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['parking','revêtement','sol','travaux']::text[], ARRAY[]::text[], '[{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true}]'::jsonb, NULL, NULL),
  ('parking-02', 'Attribution des places de parking', 'Parking et espaces communs', 'L''assemblée générale décide d''attribuer les places de parking selon les modalités suivantes : {modalites_attribution}. Les places concernées sont : {liste_places}.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['parking','attribution','places']::text[], ARRAY[]::text[], '[{"name":"modalites_attribution","type":"textarea","label":"Modalités d''attribution","required":true},{"name":"liste_places","type":"textarea","label":"Liste des places","required":true}]'::jsonb, NULL, NULL),
  ('parking-03', 'Aménagement d''un local vélos', 'Parking et espaces communs', 'L''assemblée générale décide d''aménager un local à vélos dans {emplacement}. Le local pourra accueillir {capacite} vélos. Le montant des travaux d''aménagement est de {montant_travaux} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['vélos','local','aménagement','mobilité douce']::text[], ARRAY[]::text[], '[{"name":"emplacement","type":"text","label":"Emplacement du local","required":true},{"name":"capacite","type":"numero","label":"Capacité (nombre de vélos)","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true}]'::jsonb, NULL, NULL),
  ('parking-04', 'Rénovation des espaces verts', 'Parking et espaces communs', 'L''assemblée générale décide de procéder à la rénovation des espaces verts de la copropriété. Les travaux comprennent : {description_travaux}. Le montant total est de {montant_travaux} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['espaces verts','jardin','végétation','aménagement']::text[], ARRAY[]::text[], '[{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true}]'::jsonb, NULL, NULL),
  ('parking-05', 'Installation de jeux pour enfants', 'Parking et espaces communs', 'L''assemblée générale décide d''installer une aire de jeux pour enfants dans {emplacement}. Les équipements comprennent : {liste_equipements}. Le montant total est de {montant_total} TTC, maintenance incluse pour {duree_maintenance}.', 'ART_25', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['jeux','enfants','aire de jeux','aménagement']::text[], ARRAY[]::text[], '[{"name":"emplacement","type":"text","label":"Emplacement","required":true},{"name":"liste_equipements","type":"textarea","label":"Liste des équipements","required":true},{"name":"montant_total","type":"montant","label":"Montant total TTC","required":true},{"name":"duree_maintenance","type":"text","label":"Durée maintenance incluse","required":true}]'::jsonb, NULL, NULL),
  ('parking-06', 'Création d''un local poubelles', 'Parking et espaces communs', 'L''assemblée générale décide de créer un local à poubelles dans {emplacement}. Le local respectera les normes d''hygiène et comprendra {description_amenagement}. Le montant des travaux est de {montant_travaux} TTC.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['poubelles','local','déchets','aménagement']::text[], ARRAY[]::text[], '[{"name":"emplacement","type":"text","label":"Emplacement du local","required":true},{"name":"description_amenagement","type":"textarea","label":"Description de l''aménagement","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true}]'::jsonb, NULL, NULL),
  ('assurance-01', 'Renouvellement du contrat d''assurance multirisque immeuble', 'Assurances', 'L''assemblée générale décide de renouveler le contrat d''assurance multirisque immeuble avec la compagnie {nom_assureur}. La prime annuelle est de {montant_prime} TTC. Les garanties couvrent : {liste_garanties}. Le contrat prend effet le {date_effet}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['assurance','multirisque','contrat','renouvellement']::text[], ARRAY[]::text[], '[{"name":"nom_assureur","type":"text","label":"Nom de l''assureur","required":true},{"name":"montant_prime","type":"montant","label":"Prime annuelle TTC","required":true},{"name":"liste_garanties","type":"textarea","label":"Liste des garanties","required":true},{"name":"date_effet","type":"date","label":"Date d''effet du contrat","required":true}]'::jsonb, NULL, NULL),
  ('assurance-02', 'Changement d''assureur', 'Assurances', 'L''assemblée générale décide de changer d''assureur multirisque immeuble. Le nouveau contrat sera souscrit auprès de {nom_nouvel_assureur} pour une prime annuelle de {montant_prime} TTC, contre {montant_ancien} TTC précédemment. Le syndic est autorisé à résilier le contrat actuel dans les formes légales.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['assurance','changement','résiliation','économies']::text[], ARRAY[]::text[], '[{"name":"nom_nouvel_assureur","type":"text","label":"Nouvel assureur","required":true},{"name":"montant_prime","type":"montant","label":"Nouvelle prime annuelle TTC","required":true},{"name":"montant_ancien","type":"montant","label":"Ancienne prime TTC","required":true}]'::jsonb, NULL, NULL),
  ('assurance-03', 'Souscription d''une assurance protection juridique', 'Assurances', 'L''assemblée générale décide de souscrire une assurance protection juridique auprès de {nom_assureur} pour un montant annuel de {montant_prime} TTC. Cette assurance couvre : {liste_garanties}.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['assurance','protection juridique','contentieux']::text[], ARRAY[]::text[], '[{"name":"nom_assureur","type":"text","label":"Nom de l''assureur","required":true},{"name":"montant_prime","type":"montant","label":"Prime annuelle TTC","required":true},{"name":"liste_garanties","type":"textarea","label":"Garanties couvertes","required":true}]'::jsonb, NULL, NULL),
  ('assurance-04', 'Déclaration de sinistre et autorisation de travaux', 'Assurances', 'L''assemblée générale autorise le syndic à déclarer le sinistre survenu le {date_sinistre} à l''assurance et à engager les travaux de réparation pour un montant de {montant_travaux} TTC. La franchise de {montant_franchise} sera répartie selon les tantièmes.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['sinistre','assurance','réparation','franchise']::text[], ARRAY[]::text[], '[{"name":"date_sinistre","type":"date","label":"Date du sinistre","required":true},{"name":"montant_travaux","type":"montant","label":"Montant des travaux TTC","required":true},{"name":"montant_franchise","type":"montant","label":"Montant de la franchise","required":true}]'::jsonb, NULL, NULL),
  ('assurance-05', 'Souscription d''une garantie dommages-ouvrage', 'Assurances', 'L''assemblée générale décide de souscrire une assurance dommages-ouvrage pour les travaux de {description_travaux}. Le montant de la prime est de {montant_prime} TTC. Cette assurance est obligatoire pour les travaux de construction.', 'ART_24', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['dommages-ouvrage','assurance','construction','travaux']::text[], ARRAY[]::text[], '[{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true},{"name":"montant_prime","type":"montant","label":"Montant de la prime TTC","required":true}]'::jsonb, NULL, NULL),
  ('copro-01', 'Autorisation de travaux privatifs affectant les parties communes', 'Copropriétaires', 'L''assemblée générale autorise M./Mme {nom_coproprietaire}, propriétaire du lot n° {numero_lot}, à réaliser les travaux suivants affectant les parties communes : {description_travaux}. Ces travaux seront réalisés sous la responsabilité et aux frais exclusifs du demandeur, dans le respect des règles de l''art.', 'ART_25', false, ARRAY['ORDINAIRE','EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['travaux privatifs','autorisation','parties communes']::text[], ARRAY[]::text[], '[{"name":"nom_coproprietaire","type":"coproprietaire","label":"Nom du copropriétaire","required":true},{"name":"numero_lot","type":"text","label":"Numéro du lot","required":true},{"name":"description_travaux","type":"textarea","label":"Description des travaux","required":true}]'::jsonb, NULL, NULL),
  ('copro-02', 'Régularisation d''occupation d''une partie commune', 'Copropriétaires', 'L''assemblée générale autorise la régularisation de l''occupation par M./Mme {nom_coproprietaire} de la partie commune {description_partie} moyennant une indemnité de {montant_indemnite} versée à la copropriété.', 'ART_26', false, ARRAY['EXTRAORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['régularisation','occupation','parties communes','indemnité']::text[], ARRAY[]::text[], '[{"name":"nom_coproprietaire","type":"coproprietaire","label":"Nom du copropriétaire","required":true},{"name":"description_partie","type":"text","label":"Description de la partie commune","required":true},{"name":"montant_indemnite","type":"montant","label":"Montant de l''indemnité","required":true}]'::jsonb, NULL, NULL),
  ('copro-03', 'Mise en demeure pour non-respect du règlement', 'Copropriétaires', 'L''assemblée générale autorise le syndic à mettre en demeure M./Mme {nom_coproprietaire} de cesser {description_infraction} sous {delai_jours} jours, sous peine de poursuites judiciaires aux frais du contrevenant.', 'ART_24', false, ARRAY['ORDINAIRE']::text[], ARRAY[]::text[], NULL, ARRAY['mise en demeure','infraction','règlement','poursuites']::text[], ARRAY[]::text[], '[{"name":"nom_coproprietaire","type":"coproprietaire","label":"Nom du copropriétaire","required":true},{"name":"description_infraction","type":"textarea","label":"Description de l''infraction","required":true},{"name":"delai_jours","type":"numero","label":"Délai en jours","required":true}]'::jsonb, NULL, NULL)
on conflict (code) where cabinet_id is null do nothing;
